import {afterEach,expect,it,vi} from 'vitest';
import {deferred,stateRow,syntheticHarness} from '../tests/phase2a03/transaction-fake';
import {createDormantTransactionCore,provisionalBudgets,transactionSql} from '../src/server/location/transaction.server';
afterEach(()=>vi.useRealTimers());
const kinds=(h:Awaited<ReturnType<typeof syntheticHarness>>)=>h.client.transcript.map(e=>e.kind);
it('closure independent: eight cancelled late aliases cross clean handoff while parallel aliases cannot disrupt delayed release or later COMMIT',async()=>{
 const h=await syntheticHarness();
 vi.useFakeTimers();
 let commitEntered=deferred(),commitFinish=deferred();
 h.client.hooks.set('commit',async()=>{commitEntered.resolve();await commitFinish.promise;});
 const releaseEntered=deferred(),releaseFinish=deferred();
 h.client.hooks.set('release',async()=>{releaseEntered.resolve();await releaseFinish.promise;});
 const first=h.run();await commitEntered.promise;
 const assertAliases=async()=>{
  const before=h.client.transcript.length;
  const outcomes=await Promise.all(Array.from({length:8},()=>createDormantTransactionCore(h.ports).execute(h.evidence,h.input)));
  expect(outcomes.every(r=>r.kind==='FAILURE'&&r.code==='TRANSACTION_FAILED')).toBe(true);
  expect(kinds(h).slice(before)).toEqual(Array(8).fill('acquire'));
 };
 await assertAliases();
 const late=Array.from({length:8},()=>({entered:deferred(),finish:deferred(),controller:new AbortController()}));
 const abandoned=late.map(g=>createDormantTransactionCore({...h.ports,connections:{acquire:async()=>{g.entered.resolve();await g.finish.promise;return h.client;}}}).execute(h.evidence,h.input,{signal:g.controller.signal}));
 await Promise.all(late.map(g=>g.entered.promise));late.forEach(g=>g.controller.abort());
 expect((await Promise.all(abandoned)).every(r=>r.kind==='FAILURE'&&r.code==='DATABASE_BUSY')).toBe(true);
 commitFinish.resolve();await releaseEntered.promise;await assertAliases();
 releaseFinish.resolve();expect(await first).toMatchObject({kind:'COMMITTED'});
 h.client.hooks.delete('release');commitEntered=deferred();commitFinish=deferred();
 let returned=false;const second=h.run().then(r=>{returned=true;return r;});await commitEntered.promise;
 const before=h.client.transcript.length;late.forEach(g=>g.finish.resolve());await vi.advanceTimersByTimeAsync(0);
 expect(kinds(h).slice(before)).toEqual([]);expect(returned).toBe(false);
 await assertAliases();commitFinish.resolve();expect(await second).toMatchObject({kind:'COMMITTED',disposition:'DUPLICATE'});
 expect(kinds(h).filter(k=>k==='begin')).toHaveLength(2);
 expect(kinds(h).filter(k=>k==='release')).toHaveLength(2);expect(kinds(h)).not.toContain('discard');
 expect(h.store.versions).toHaveLength(1);
});
it('closure independent: delayed failed discard after timeout cannot resurrect old object or erase eight-alias protection of replacement',async()=>{
 const h=await syntheticHarness();vi.useFakeTimers();
 const old=h.client;old.ack={kind:'UNKNOWN'};
 const entered=deferred(),finish=deferred();old.hooks.set('discard',async()=>{entered.resolve();await finish.promise;});old.failures.set('discard',Error('synthetic'));
 const first=h.run();await entered.promise;
 await vi.advanceTimersByTimeAsync(provisionalBudgets.cleanupMs+1);
 expect(await first).toMatchObject({kind:'FAILURE',code:'COMMIT_OUTCOME_UNKNOWN'});
 h.replaceClient();const commitEntered=deferred(),commitFinish=deferred();
 h.client.hooks.set('commit',async()=>{commitEntered.resolve();await commitFinish.promise;});
 const next=h.run();await commitEntered.promise;finish.resolve();await vi.advanceTimersByTimeAsync(0);
 const before=h.client.transcript.length;
 expect((await Promise.all(Array.from({length:8},()=>h.run())))).toHaveLength(8);
 expect(kinds(h).slice(before)).toEqual(Array(8).fill('acquire'));
 const oldCore=createDormantTransactionCore({...h.ports,connections:{acquire:async()=>old}});
 old.hooks.delete('discard');old.failures.clear();const oldBefore=old.transcript.length;
 expect(await oldCore.execute(h.evidence,h.input)).toMatchObject({kind:'FAILURE',code:'TRANSACTION_FAILED'});
 expect(old.transcript.slice(oldBefore).map(e=>e.kind)).toEqual(['discard']);
 commitFinish.resolve();expect(await next).toMatchObject({kind:'COMMITTED'});
 expect(h.store.versions).toHaveLength(1);
});
it('closure independent: committing rejected wrong-property CAS leaves persistent state byte-equivalent',async()=>{
 const h=await syntheticHarness();h.store.state=stateRow();const before=structuredClone(h.store);
 const options={signal:new AbortController().signal,timeoutMs:1000};
 await h.client.query(transactionSql.begin,[],options);
 expect(await h.client.query(transactionSql.cas,['f9000000-0000-0000-0000-000000000009','f8000000-0000-0000-0000-000000000008',0,null],options)).toEqual({rows:[],rowCount:0});
 expect(h.store).toEqual(before);expect(h.client.active).toEqual(before);
 expect(await h.client.commit(options)).toEqual({kind:'COMMITTED'});expect(h.store).toEqual(before);
});
